import 'inspect-raw.dart' as raw;
void main(){const p='/private/tmp/dart3d-u3-outline-view-probe-20261028/r1/parent';final rows=Directory('$p/raw').listSync().whereType<File>().where((f)=>f.path.endsWith('.json')).map((f){final m=jsonDecode(f.readAsStringSync()) as Map;m['path']=f.path.replaceAll('.json','.rgba');return m;}).toList();final b=rows.firstWhere((m)=>m['label'].toString().startsWith('target ')&&m['label'].contains('mode=0'));final base=File(b['path']).readAsBytesSync();final mask=rows.firstWhere((m)=>m['label'].toString().startsWith('mask ')&&m['label'].contains('time=539796.3166666668'));final bytes=File(mask['path']).readAsBytesSync();var selectedOutsideBase=0,baseOutsideSelected=0;final locations=<List<int>>[];for(var i=0;i<base.length~/4;i++){final alpha=raw.half(bytes[i*8+6]|bytes[i*8+7]<<8);if(alpha>0&&base[i*4+3]==0)selectedOutsideBase++;if(alpha==0&&base[i*4+3]>0){baseOutsideSelected++;locations.add([i%96,i~/96]);}}File('$p/mask-alignment.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert({'maskIsHistoricalSelectedState':true,'selectedMaskOutsideBasePixels':selectedOutsideBase,'baseOutsideSelectedPixels':baseOutsideSelected,'baseOnlyLocations':locations,'base':b['label'],'mask':mask['label']}));print('Selected mask outside base=$selectedOutsideBase; base-only pixels=$baseOutsideSelected');}
